	/** 
	 * jumpstart the process by instantiating2 Regulation
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		regulationId = RegulationService.getRegulationInstance()
		.createRegulation( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		RegulationService.getRegulationInstance()
				.createRegulation( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.regulationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Regulation : " + successValue.getRegulationId());
							  if (successValue.getRegulationId().equals(regulationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRegulationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Regulation test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on regulation consumed")
					);
			subscriber.regulationSubscribe( regulationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Regulation : " + successValue.getRegulationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRegulationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on regulation for regulationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Regulation. 
	 */
	protected Regulation read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Regulation" );

		Regulation entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Regulation with primary key" );
		msg.append( regulationId );
		
		RegulationFetchOneSummary fetchOneSummary = new RegulationFetchOneSummary( regulationId );

		try {
			entity = RegulationService.getRegulationInstance().getRegulation( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Regulation " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Regulation.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Regulation." );

		StringBuilder msg = new StringBuilder( "Failed to update a Regulation : " );        
		Regulation entity = read();
		UpdateRegulationCommand command = generateUpdateCommand();
		command.setRegulationId(entity.getRegulationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Regulation." );

			// for use later on...
			regulationId = entity.getRegulationId();

			RegulationService proxy = RegulationService.getRegulationInstance();  

			proxy.updateRegulation( command ).get();

			LOGGER.info( "-- Successfully saved Regulation - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + regulationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Regulation.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Regulation." );

		Regulation entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Regulation with id " + regulationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Regulation with id " + regulationId );

			throw e;
		}

		try{
			RegulationService.getRegulationInstance().delete( new DeleteRegulationCommand( entity.getRegulationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Regulation with id " + regulationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Regulation with id " + regulationId );

			throw e;
		}
	}

	/**
	 * get all Regulations.
	 */
	protected List<Regulation> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Regulations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Regulation : " );        
		List<Regulation> collection  = new ArrayList<>();

		try {
			// call the static get method on the RegulationService
			collection = RegulationService.getRegulationInstance().getAllRegulation();
			assertNotNull( collection, "An Empty collection of Regulation was incorrectly returned.");
			
			// Now print out the values
			Regulation entity = null;            
			Iterator<Regulation> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRegulationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

